CREATE DATABASE IF NOT EXISTS real_estate_db; USE real_estate_db;
CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(100) NOT NULL,role ENUM('ADMIN','MANAGER','TENANT') NOT NULL DEFAULT 'TENANT',phone VARCHAR(30),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS properties(id INT PRIMARY KEY AUTO_INCREMENT,manager_id INT,title VARCHAR(150) NOT NULL,address VARCHAR(255) NOT NULL,city VARCHAR(80),rent DECIMAL(12,2) NOT NULL,property_type VARCHAR(50),bedrooms INT DEFAULT 0,description TEXT,status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(manager_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS rental_applications(id INT PRIMARY KEY AUTO_INCREMENT,property_id INT NOT NULL,tenant_id INT NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',message TEXT,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,FOREIGN KEY(tenant_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS rental_agreements(id INT PRIMARY KEY AUTO_INCREMENT,application_id INT NOT NULL UNIQUE,start_date DATE NOT NULL,end_date DATE NOT NULL,rent DECIMAL(12,2) NOT NULL,status ENUM('ACTIVE','EXPIRED','TERMINATED') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES rental_applications(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages(id INT PRIMARY KEY AUTO_INCREMENT,sender_id INT NOT NULL,receiver_id INT NOT NULL,message TEXT NOT NULL,sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(receiver_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,message VARCHAR(255) NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_logs(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT,action VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS system_settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255));
INSERT IGNORE INTO system_settings VALUES('site_name','Online Real Estate Management System');

